```c
fib(n) {
  if (n > M) error();
  if (n == 0) return 1;
  if (n == 1) return 1;
  if (f[n] != 0)      /* (1) */
    return f[n];      /* (2) */
  t = fib(n-1) + fib(n-2);
  f[n] = t;           /* (3) */
  return t;
}
